// CompactSessionCRDT compacts a document's CRDT state for a caller whose
// device identity was resolved from a session by the HTTP layer, delegating
// to the CRDT state service's gated compaction: the registration/permission
// verdict is taken inside the same serialized transaction as the trim, so a
// revoked device trims nothing and a rejected request observes no state
// content. It is the session counterpart to CompactCRDT; the trimming,
// retained identities, snapshot body and persistence semantics are
// identical.
func (a *App) CompactSessionCRDT(documentID, deviceID string) (crdt.Snapshot, error) {
	return a.crdt.Compact(documentID, deviceID)
}

// GetCRDTSnapshot delegates to the CRDT state service.
func (a *App) GetCRDTSnapshot(documentID string) (crdt.Snapshot, error) {
	return a.crdt.GetSnapshot(documentID)
}

// OpenCRDTSubscription delegates to the CRDT state service.
func (a *App) OpenCRDTSubscription(documentID, deviceID string) (*crdt.State, *crdt.Subscription, func(), error) {
	return a.crdt.OpenSubscription(documentID, deviceID)
}

// AddCRDTSubscription delegates to the CRDT state service.
func (a *App) AddCRDTSubscription(documentID, deviceID string) (*crdt.Subscription, func()) {
	return a.crdt.AddSubscription(documentID, deviceID)
}

// RegisterPush records one freshly established push connection in the
// process-wide in-memory registry. The returned subscription carries the
// server-allocated id and the one-shot active-cancel signal; the connection
// layer removes it when the connection ends.
func (a *App) RegisterPush(deviceID, documentID string, kind push.Kind, cursor int64) *push.Subscription {
	return a.pushSubs.Register(deviceID, documentID, kind, cursor)
}

// UnregisterPush removes an ended push connection.
func (a *App) UnregisterPush(subscriptionID string) {
	a.pushSubs.Unregister(subscriptionID)
}

// ListPushSubscriptions returns the device's live push connections across
// both channels in establishment order. It is a pure memory view.
func (a *App) ListPushSubscriptions(deviceID string) []push.Info {
	return a.pushSubs.List(deviceID)
}

// CancelPushSubscription actively ends one of the device's live push
// connections. It returns false when the id is unknown, already gone, or owned
// by another device; those cases are one indistinguishable 404 at the edge.
func (a *App) CancelPushSubscription(deviceID, subscriptionID string) bool {
	return a.pushSubs.Cancel(deviceID, subscriptionID)
}

// CloseDocumentPush ends every live push connection subscribed to documentID,
// across both channels and every owning device, after its deletion committed.
// Other documents' connections are untouched.
func (a *App) CloseDocumentPush(documentID string) {
	a.pushSubs.CloseDocument(documentID)
}

package server

import (
	"errors"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// sessionChangeLookupRequest is the body of POST
// .../sessions/{sessionId}/documents/{documentId}/changes/query: only the
// non-empty, in-batch-unique set of change ids travels in the request. The
// calling device is the session's owning device, resolved from the path with
// the same identity rule as the session reads, exports, commits, replays,
// merges, compactions, polls and subscriptions — no new credential is
// introduced. A stray deviceId is decoded and ignored like every other unknown
// field, so it can never override the session owner.
type sessionChangeLookupRequest struct {
	IDs []string `json:"ids"`
}

// handleSessionQueryChanges is the session view's counterpart to the
// document-level read-only batch lookup:
//
//	POST /v1/sessions/{sessionId}/documents/{documentId}/changes/query
//
// The strict application/json body names a non-empty array of non-empty,
// in-batch-unique change ids; answers arrive in the exact order the ids were
// given and use the same changeLookupItem/changeLookupResponse shape the
// document-level lookup emits. Each id is answered independently:
//
//   - "found": the change is still in the online log, so the answer carries
//     its originating device, the payload verbatim as it was saved at commit
//     time and its first cursor;
//   - "compacted": compaction trimmed the row, so the answer reports only the
//     first cursor held in its retained summary — no payload is restored and
//     the summary never participates in an ordinary read;
//   - "missing": the id has never belonged to the document, so the answer
//     carries no content. A missing id is a normal answer, not an error.
//
// Checks run in the fixed order request shape (400) first — content type,
// JSON validity, trailing content, a missing or empty ids array, an empty or
// mistyped element and an in-batch duplicate — then session existence (404)
// and document permission (403). A 404 or 403 exposes no change content. The
// query creates no change, allocates no cursor and wakes neither a long poll
// nor a push subscriber. Success is one compact JSON line ending in a newline
// with results then count.
func handleSessionQueryChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	var req sessionChangeLookupRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	// A missing (nil) or empty ids array is the same request-shape error; a
	// non-string element was already rejected while decoding the JSON.
	if len(req.IDs) == 0 {
		writeError(w, http.StatusBadRequest, "ids must be a non-empty array of non-empty strings")
		return
	}
	seen := make(map[string]struct{}, len(req.IDs))
	for _, id := range req.IDs {
		if id == "" {
			writeError(w, http.StatusBadRequest, "each id must be a non-empty string")
			return
		}
		if _, dup := seen[id]; dup {
			writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+id)
			return
		}
		seen[id] = struct{}{}
	}

	// Request shape is settled; only now does the session lookup run, so a
	// malformed query against an unknown session is still a 400.
	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	// The lookup is the same gated read the document-level batch query uses:
	// the registration/permission verdict is retaken inside its serialized
	// transaction, so a session whose device was deregistered between the two
	// lookups answers 404 and a revoked device answers 403 before any change
	// content is observed.
	lookups, err := s.GetChangesByIDs(documentID, deviceID, req.IDs)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			// The session's device was deregistered between the lookup and the
			// query; its cascade removed the session too, so the identity the
			// caller used no longer exists.
			writeError(w, http.StatusNotFound, "session not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		default:
			writeError(w, http.StatusInternalServerError, "failed to look up changes")
		}
		return
	}

	items := make([]changeLookupItem, len(lookups))
	for i, l := range lookups {
		items[i] = changeLookupItem{
			ID:       l.ID,
			Status:   l.Status,
			DeviceID: l.DeviceID,
			Payload:  l.Payload,
			Cursor:   l.Cursor,
		}
	}
	writeJSON(w, http.StatusOK, changeLookupResponse{Results: items, Count: len(items)})
}

// malformedSessionQueryPath reports whether p targets the session-scoped
// change-log batch lookup but is not at its exact location
// (/v1/sessions/{sessionId}/documents/{documentId}/changes/query): a missing
// "documents"/"changes" segment, an extra segment, a trailing slash (an empty
// trailing segment), or a "query" segment in a position short of the
// registered shape. ServeMux would answer those with a redirect or a
// plain-text 404/405; every failure of this endpoint must be a JSON 400
// instead and never a redirect. Empty segments are already rejected by the
// guard itself.
//
// "query" is treated as the endpoint keyword only in its terminal segment
// position (the fifth segment, index 4); a session or document identifier
// literally named "query" occupies an identifier position (index 0 or 2) and
// keeps its ordinary routes.
func malformedSessionQueryPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guard; "query" there is an ordinary identifier, not the
	// changes-query keyword.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	for i, seg := range segs {
		if seg != "query" {
			continue
		}
		// Identifier positions: sessionId (0) and documentId (2). A value of
		// "query" there is an ordinary identifier, not the endpoint word.
		if i == 0 || i == 2 {
			continue
		}
		// Endpoint keyword position: the fifth segment must be exactly "query"
		// with the documents/changes scaffolding around it, and no segment may
		// follow. Any other occurrence is a malformed path.
		if i == 4 && len(segs) == 5 &&
			segs[0] != "" &&
			segs[1] == "documents" &&
			segs[2] != "" &&
			segs[3] == "changes" {
			return false
		}
		return true
	}
	return false
}

// Package events is the change event service: the durable per-document change
// log together with everything written on top of it.
//
// Within a document every change has a client-supplied id. New ids receive a
// monotonically increasing cursor; re-posting an existing id is idempotent
// only when the deviceId and decoded JSON payload match, otherwise it is a
// conflict. Valid batches commit atomically in one serialized transaction, so
// cursors never repeat and no record is partially written, even under
// concurrent writers. Ordinary posts, offline replays, merges and snapshot
// restores all allocate from the same per-document contiguous cursor space.
//
// A document may also carry snapshots: caller-supplied JSON states pinned to
// existing change cursors. Snapshots are write-once per cursor — a matching
// re-post is idempotent, a differing one a conflict — and live apart from the
// change log. A restore appends an ordinary change whose payload is a
// snapshot's state, recording its provenance so a repeated restore after a
// restart keeps the same idempotency/conflict decisions.
//
// Reads page by cursor in ascending order. The session view and the document
// view are the same read; the HTTP layer adds the session/permission checks.
// Long polling and push subscriptions are in-memory observers of commits:
// they register before the confirming read, hold no durable state, and are
// woken only after a change-bearing transaction has committed.
//
// The service owns only its own tables. The registration and permission
// layers are reached through its Gate interface, so a replay or merge never
// reaches into another service's storage.
package events

import (
	"encoding/json"
	"errors"
	"fmt"
)

// ErrStoreClosing reports that the service is shutting down and parked long
// polls have been woken so they can return without writing anything. The
// caller maps it to 503.
var ErrStoreClosing = errors.New("store is closing")

// Change is one element of an inbound batch or one row of a listing.
type Change struct {
	ID       string          // client-supplied change id, unique per document
	DeviceID string          // originating device
	Payload  json.RawMessage // decoded JSON value, stored verbatim
}

// Result reports the outcome for one element of an accepted batch.
type Result struct {
	ID      string `json:"id"`
	Created bool   `json:"created"`
	Cursor  int64  `json:"cursor"`
}

// ListedChange is one row in a ListChanges response.
type ListedChange struct {
	ID       string          `json:"id"`
	DeviceID string          `json:"deviceId"`
	Payload  json.RawMessage `json:"payload"`
	Cursor   int64           `json:"cursor"`
}

// MergeResult reports the outcome of an accepted MergeChange. Outcome is one
// of "idempotent", "applied" or "merged".
type MergeResult struct {
	ID      string  `json:"id"`
	Outcome string  `json:"outcome"`
	Cursor  int64   `json:"cursor"`
	Result  *Result `json:"result,omitempty"`
}

// ErrConflict reports that a batch references an existing change id with a
// different deviceId or payload. The whole batch is rejected.
type ErrConflict struct {
	ID string
}

func (e *ErrConflict) Error() string {
	return fmt.Sprintf("conflicting change %q for document", e.ID)
}

// ErrStaleCursor reports that a merge targets a base cursor for an unknown
// document, or a base cursor greater than the document's current cursor. The
// caller maps it to 400; nothing is written.
var ErrStaleCursor = errors.New("baseCursor is unknown or ahead of the current cursor")

// ErrSnapshotBase reports that a snapshot targets an unknown document or a
// cursor that is not an existing change cursor of the document. The caller
// maps it to 400; nothing is written.
var ErrSnapshotBase = errors.New("snapshot cursor is not an existing cursor of the document")

// ErrCompactedBase reports that a merge targets a base cursor below the
// document's compaction boundary: the changes it would be checked against
// have left the online log, so the conflict check cannot be completed. The
// caller maps it to 400; nothing is written.
var ErrCompactedBase = errors.New("baseCursor is below the compaction boundary")

// ErrSnapshotNotFound reports that no snapshot exists for the document and
// cursor. The caller maps it to 404.
var ErrSnapshotNotFound = errors.New("snapshot not found")

// ErrSnapshotConflict reports that a snapshot already exists for the document
// and cursor with a different state. The stored snapshot is left unchanged.
type ErrSnapshotConflict struct {
	Cursor int64
}

func (e *ErrSnapshotConflict) Error() string {
	return fmt.Sprintf("conflicting snapshot for cursor %d", e.Cursor)
}

// ErrRestoreConflict reports that a restore references a change id that is
// already taken by an ordinary change, or by a prior restore whose deviceId,
// snapshot cursor or source state differs. Nothing is written; the caller maps
// it to 409.
type ErrRestoreConflict struct {
	ID string
}

func (e *ErrRestoreConflict) Error() string {
	return fmt.Sprintf("change id %q conflicts with the change log", e.ID)
}

// ExportedSnapshot is one row of an ExportSnapshots result.
type ExportedSnapshot struct {
	Cursor int64           `json:"cursor"`
	State  json.RawMessage `json:"state"`
}

// ErrVersionConflict reports that a version registration or rename cannot be
// applied: the version name is already bound to a different snapshot cursor,
// or the requested bind would move an existing name (and zero writes is the
// required outcome). The caller maps it to 409.
type ErrVersionConflict struct {
	Name string
}

func (e *ErrVersionConflict) Error() string {
	return fmt.Sprintf("snapshot version %q is bound to another cursor", e.Name)
}

// ErrVersionNotFound reports that no snapshot version of the document carries
// the requested name. The caller maps it to 404.
var ErrVersionNotFound = errors.New("snapshot version not found")

// SnapshotVersion is one row of a ListSnapshotVersions result: the version
// name together with the snapshot cursor it points at.
type SnapshotVersion struct {
	Name   string `json:"name"`
	Cursor int64  `json:"snapshotCursor"`
}

// VersionResult reports the outcome of registering or renaming a snapshot
// version: the version name and the snapshot cursor it is bound to. An
// idempotent registration returns the same body as the first registration.
type VersionResult struct {
	Name   string `json:"name"`
	Cursor int64  `json:"snapshotCursor"`
}

// RestoreResult reports the outcome of an accepted RestoreSnapshot.
type RestoreResult struct {
	ID           string `json:"id"`
	Created      bool   `json:"created"`
	Cursor       int64  `json:"cursor"`
	RestoredFrom int64  `json:"restoredFrom"`
}

// schema is created when the service is constructed. Table and index shapes
// are unchanged from the pre-refactor layout, so data already on disk stays
// readable.
const schema = `
CREATE TABLE IF NOT EXISTS changes (
	document_id TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	id          TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	payload     BLOB NOT NULL,
	PRIMARY KEY (document_id, id)
);
CREATE UNIQUE INDEX IF NOT EXISTS changes_doc_cursor_idx
	ON changes(document_id, cursor);
CREATE TABLE IF NOT EXISTS snapshots (
	document_id TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	state       BLOB NOT NULL,
	PRIMARY KEY (document_id, cursor)
);
CREATE TABLE IF NOT EXISTS restores (
	document_id     TEXT NOT NULL,
	change_id       TEXT NOT NULL,
	device_id       TEXT NOT NULL,
	snapshot_cursor INTEGER NOT NULL,
	change_cursor   INTEGER NOT NULL,
	state           BLOB NOT NULL,
	PRIMARY KEY (document_id, change_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS restores_doc_cursor_idx
	ON restores(document_id, change_cursor);
CREATE TABLE IF NOT EXISTS change_boundaries (
	document_id TEXT NOT NULL PRIMARY KEY,
	boundary    INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS change_identities (
	document_id   TEXT NOT NULL,
	id            TEXT NOT NULL,
	device_id     TEXT NOT NULL,
	digest        BLOB NOT NULL,
	cursor        INTEGER NOT NULL,
	restored_from INTEGER,
	PRIMARY KEY (document_id, id)
);
CREATE TABLE IF NOT EXISTS snapshot_versions (
	document_id TEXT NOT NULL,
	name        TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	PRIMARY KEY (document_id, name)
);
`

