609		h, _ := newTestHandler(t)
610		seedDoc(t, h, "doc1", 1)
611	
612		w, body := postJSON(t, h, "/v1/documents/doc1/snapshots", `{"cursor":1,"state":{"v":1}}`)
613		if w.Code != http.StatusOK || body["created"] != true {
614			t.Fatalf("first = %d %v", w.Code, body)
615		}
616	
617		// Decoded-equal retry (different key order and number format) is idempotent.
618		w, body = postJSON(t, h, "/v1/documents/doc1/snapshots", `{"cursor":1,"state":{"v":1.0}}`)
