624		w, _ = postJSON(t, h, "/v1/documents/doc1/snapshots", `{"cursor":1,"state":{"v":2}}`)
625		if w.Code != http.StatusConflict {
626			t.Fatalf("conflict status = %d", w.Code)
627		}
628		var errBody map[string]string
629		if err := json.Unmarshal(w.Body.Bytes(), &errBody); err != nil || errBody["error"] == "" {
630			t.Fatalf("conflict body = %s", w.Body.String())
631		}
632		_, body = doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots/1")
633		if body["state"].(map[string]any)["v"].(float64) != 1 {
634			t.Fatalf("state after conflict = %v", body["state"])
635		}
636	}
