1015			"deviceId": "dev", "changeId": "r1", "snapshotCursor": 1,
1016		})
1017		if w.Code != http.StatusOK || body["created"] != false || body["cursor"].(float64) != 2 {
1018			t.Fatalf("replay after restart = %d %v", w.Code, body)
1019		}
1020		// A differing device is still a 409 after restart.
1021		w, _ = restoreJSON(t, h2, "doc1", map[string]any{
