1023		})
1024		if w.Code != http.StatusConflict {
1025			t.Fatalf("conflict after restart = %d", w.Code)
1026		}
1027		// The appended change with snapshot state reads back.
1028		w, list := doRequest(t, h2, http.MethodGet, "/v1/documents/doc1/changes?after=1")
1029		if w.Code != http.StatusOK {
1030			t.Fatal(w.Body.String())
1031		}
1032		rows := list["changes"].([]any)
1033		if len(rows) != 1 || rows[0].(map[string]any)["payload"].(map[string]any)["a"].(float64) != 1 {
1034			t.Fatalf("restored change after restart = %v", rows)
1035		}
1036	}
