309	// Fixed verdict order: request shape (400) -> device existence (404) ->
310	// document permission (403) -> version/snapshot existence (404). An earlier
311	// failure masks every later one and exposes no version content.
312	func TestSnapshotVersionFailureOrdering(t *testing.T) {
313		h, _ := newTestHandler(t)
314		seedVersionFixture(t, h, "dev-1", "doc")
315		registerVersion(t, h, "doc", "dev-1", "v1", 1)
316		registerDevice(t, h, "dev-2")
317		registerDevice(t, h, "dev-rev")
318		w, _ := postJSON(t, h, "/v1/documents/doc/permissions", map[string]any{
319			"deviceId": "dev-rev", "action": "revoke",
320		})
321		if w.Code != http.StatusOK {
322			t.Fatal(w.Body.String())
323		}
324	
325		collection := "/v1/documents/doc/snapshots/versions"
326		item := "/v1/documents/doc/snapshots/versions/v1"
327		restore := item + "/restore"
328	
329		shapeCases := []struct {
330			name   string
331			method string
332			path   string
333			body   string
334		}{
335			{"register wrong content type", http.MethodPost, collection, `{"deviceId":"dev-1","name":"x","snapshotCursor":1}`},
336			{"register bad json", http.MethodPost, collection, `{not json`},
337			{"register trailing data", http.MethodPost, collection, `{"deviceId":"dev-1","name":"x","snapshotCursor":1} garbage`},
338			{"register missing deviceId", http.MethodPost, collection, `{"name":"x","snapshotCursor":1}`},
339			{"register empty name", http.MethodPost, collection, `{"deviceId":"dev-1","name":"","snapshotCursor":1}`},
340			{"register missing cursor", http.MethodPost, collection, `{"deviceId":"dev-1","name":"x"}`},
341			{"register zero cursor", http.MethodPost, collection, `{"deviceId":"dev-1","name":"x","snapshotCursor":0}`},
342			{"register string cursor", http.MethodPost, collection, `{"deviceId":"dev-1","name":"x","snapshotCursor":"1"}`},
343			{"register float cursor", http.MethodPost, collection, `{"deviceId":"dev-1","name":"x","snapshotCursor":1.5}`},
344			{"register null cursor", http.MethodPost, collection, `{"deviceId":"dev-1","name":"x","snapshotCursor":null}`},
345			{"rename missing cursor", http.MethodPut, item, `{"deviceId":"dev-1"}`},
346			{"rename empty deviceId", http.MethodPut, item, `{"deviceId":"","snapshotCursor":1}`},
347			{"restore missing changeId", http.MethodPost, restore, `{"deviceId":"dev-1"}`},
348			{"restore empty changeId", http.MethodPost, restore, `{"deviceId":"dev-1","changeId":""}`},
349			{"wrong method GET on restore", http.MethodGet, restore, ""},
350			{"wrong method POST on item", http.MethodPost, item, ""},
351			{"wrong method PUT on collection", http.MethodPut, collection, ""},
352			{"extra segment", http.MethodGet, item + "/extra", ""},
353			{"restore extra segment", http.MethodPost, restore + "/x", ""},
354			{"trailing slash collection", http.MethodGet, collection + "/", ""},
355		}
356		for _, tc := range shapeCases {
357			t.Run("shape/"+tc.name, func(t *testing.T) {
358				ct := "application/json"
359				if tc.name == "register wrong content type" {
360					ct = "text/plain"
361				}
362				r := newJSONRequest(tc.method, tc.path, tc.body, ct)
363				if tc.method == http.MethodGet {
364					r.Header.Del("Content-Type")
365				}
366				w := serveRecorder(h, r)
367				if w.Code != http.StatusBadRequest {
368					t.Fatalf("%s %s = %d, want 400, body = %s", tc.method, tc.path, w.Code, w.Body.String())
369				}
370				assertJSONError(t, w)
371			})
372		}
373	
374		// The "missing deviceId on list" case is really a 404 (an empty caller is
375		// indistinguishable from an unregistered one), checked explicitly.
376		w, _ = doRequest(t, h, http.MethodGet, collection)
377		if w.Code != http.StatusNotFound {
378			t.Fatalf("list without deviceId = %d, want 404", w.Code)
379		}
380	
381		// Device existence precedes permission and content, on every verb.
382		if w, _ := postJSON(t, h, collection, map[string]any{"deviceId": "ghost", "name": "g", "snapshotCursor": 1}); w.Code != http.StatusNotFound {
383			t.Fatalf("register unknown device = %d, want 404", w.Code)
384		}
385		if w, _ := doRequest(t, h, http.MethodGet, item+"?deviceId=ghost"); w.Code != http.StatusNotFound {
386			t.Fatalf("read unknown device = %d, want 404", w.Code)
387		}
388		if w, _ := doRequest(t, h, http.MethodDelete, item+"?deviceId=ghost"); w.Code != http.StatusNotFound {
389			t.Fatalf("delete unknown device = %d, want 404", w.Code)
390		}
391	
392		// Permission precedes version/snapshot existence: a revoked caller is 403
393		// even against a name or snapshot that exists (or one that does not).
394		if w, _ := postJSON(t, h, collection, map[string]any{"deviceId": "dev-rev", "name": "anything", "snapshotCursor": 1}); w.Code != http.StatusForbidden {
395			t.Fatalf("register revoked = %d, want 403", w.Code)
396		}
397		if w, _ := doRequest(t, h, http.MethodGet, item+"?deviceId=dev-rev"); w.Code != http.StatusForbidden {
398			t.Fatalf("read revoked = %d, want 403", w.Code)
399		}
400		if w, _ := doRequest(t, h, http.MethodGet, collection+"?deviceId=dev-rev"); w.Code != http.StatusForbidden {
401			t.Fatalf("list revoked = %d, want 403", w.Code)
402		}
403		if w, _ := doRequest(t, h, http.MethodDelete, collection+"/missing?deviceId=dev-rev"); w.Code != http.StatusForbidden {
404			t.Fatalf("delete missing-name revoked = %d, want 403 (permission precedes existence)", w.Code)
405		}
406	
407		// Content existence is last: an authorized device gets a 404 for a
408		// missing name or a missing target snapshot.
409		if w, _ := doRequest(t, h, http.MethodGet, collection+"/missing?deviceId=dev-1"); w.Code != http.StatusNotFound {
410			t.Fatalf("read missing name = %d, want 404", w.Code)
411		}
412		if w, _ := doRequest(t, h, http.MethodDelete, collection+"/missing?deviceId=dev-1"); w.Code != http.StatusNotFound {
413			t.Fatalf("delete missing name = %d, want 404", w.Code)
414		}
415		if w, _ := postJSON(t, h, collection, map[string]any{"deviceId": "dev-1", "name": "fresh", "snapshotCursor": 99}); w.Code != http.StatusNotFound {
416			t.Fatalf("register missing snapshot = %d, want 404", w.Code)
417		}
418		if w := serveRecorder(h, newJSONRequest(http.MethodPut, collection+"/v1",
419			`{"deviceId":"dev-1","snapshotCursor":99}`, "application/json")); w.Code != http.StatusNotFound {
420			t.Fatalf("rename to missing snapshot = %d, want 404", w.Code)
421		}
422	}
