582	// Concurrent registrations of distinct names all land; repeated attempts to
583	// bind one name to the same cursor are all idempotent 200s, and an attempted
584	// rebind to a different cursor never leaves a torn state.
585	func TestSnapshotVersionConcurrent(t *testing.T) {
586		h, _ := newTestHandler(t)
587		seedVersionFixture(t, h, "dev-1", "doc")
588	
589		const n = 30
590		var wg sync.WaitGroup
591		start := make(chan struct{})
592		statuses := make([]int, n)
593		for i := 0; i < n; i++ {
594			wg.Add(1)
595			go func(i int) {
596				defer wg.Done()
597				<-start
598				name := fmt.Sprintf("vn-%02d", i)
599				w, _ := postJSON(t, h, "/v1/documents/doc/snapshots/versions", map[string]any{
600					"deviceId": "dev-1", "name": name, "snapshotCursor": 1,
601				})
602				statuses[i] = w.Code
603			}(i)
604		}
605		close(start)
606		wg.Wait()
607		for i, code := range statuses {
608			if code != http.StatusOK {
609				t.Fatalf("register %d = %d, want 200", i, code)
610			}
611		}
612	
613		// Many concurrent idempotent re-binds of one name to the same cursor.
614		const m = 20
615		wg2 := sync.WaitGroup{}
616		start2 := make(chan struct{})
617		codes2 := make([]int, m)
618		for i := 0; i < m; i++ {
619			wg2.Add(1)
620			go func(i int) {
621				defer wg2.Done()
622				<-start2
623				w, _ := postJSON(t, h, "/v1/documents/doc/snapshots/versions", map[string]any{
624					"deviceId": "dev-1", "name": "vn-00", "snapshotCursor": 1,
625				})
626				codes2[i] = w.Code
627			}(i)
628		}
629		close(start2)
630		wg2.Wait()
631		for _, code := range codes2 {
632			if code != http.StatusOK {
633				t.Fatalf("idempotent concurrent rebind = %d, want 200", code)
634			}
635		}
636	
637		w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/snapshots/versions?deviceId=dev-1")
638		if w.Code != http.StatusOK {
639			t.Fatalf("list = %d", w.Code)
640		}
641		if int(body["count"].(float64)) != n {
642			t.Fatalf("count = %v, want %d", body["count"], n)
643		}
644	}
645	
646	// A version name that collides with an endpoint keyword ("merge", "restore",
647	// "versions") is an ordinary identifier in the name segment and keeps the
648	// version item routes, including the by-name restore nested under it.
649	func TestSnapshotVersionKeywordNamedVersions(t *testing.T) {
650		h, _ := newTestHandler(t)
651		seedVersionFixture(t, h, "dev-1", "doc")
652	
653		for _, name := range []string{"merge", "restore", "versions", "poll", "subscribe"} {
654			registerVersion(t, h, "doc", "dev-1", name, 1)
655			w := serveRecorder(h, newJSONRequest(http.MethodGet,
656				fmt.Sprintf("/v1/documents/doc/snapshots/versions/%s?deviceId=dev-1", name), "", ""))
657			if w.Code != http.StatusOK {
658				t.Fatalf("read version named %q = %d %s", name, w.Code, w.Body.String())
659			}
660			w, _ = doRequest(t, h, http.MethodDelete,
661				fmt.Sprintf("/v1/documents/doc/snapshots/versions/%s?deviceId=dev-1", name))
662			if w.Code != http.StatusOK {
663				t.Fatalf("delete version named %q = %d %s", name, w.Code, w.Body.String())
664			}
665		}
666	
667		// A version literally named "restore" restored by name via the nested
668		// restore segment.
669		registerVersion(t, h, "doc", "dev-1", "restore", 2)
670		w, _ := postJSON(t, h, "/v1/documents/doc/snapshots/versions/restore/restore", map[string]any{
671			"deviceId": "dev-1", "changeId": "rr1",
672		})
673		if w.Code != http.StatusOK {
674			t.Fatalf("by-name restore of version named restore = %d %s", w.Code, w.Body.String())
675		}
676		if got := strings.TrimSpace(w.Body.String()); got != `{"id":"rr1","created":true,"cursor":3,"restoredFrom":2}` {
